	<div class="ab" style="left:16px;right:16px;top:138px;height:14px;border-radius:7px;background:var(--tr)"><i class="ab" style="left:0;top:0;bottom:0;width:${o.pct}%;background:var(--ac);border-radius:7px 0 0 7px"></i>${ticks}<u class="ab" style="left:${o.pct}%;top:-5px;width:8px;height:24px;margin-left:-4px;border-radius:3px;background:var(--tx)"></u></div>
