 keys:[['◀/▶','Pick a band',null],['▲/▼','Change it',null],['L2/R2','Previous / next preset (today Y / X)',null],['Y','Equalizer on / off (today SELECT)',null],['A','Save',null],['X','Preset options: All presets, Save as new, Rename, Delete, Reset (today START)','eq-presets'],['B','Close','music']],
