// ---------- added: Adjust; state that is away from normal ----------
const bip=(v,held)=>{const p=50+v/2,on=v!=0;return `<div class="sl"><i style="left:${Math.min(50,p)}%;width:${Math.abs(v)/2}%;border-radius:0;${on?'':'display:none'}"></i><b class="ab" style="left:50%;top:-4px;width:2px;height:${held?24:22}px;margin-left:-1px;background:var(--dm)"></b><u style="left:${p}%;${held?'width:14px;height:30px;top:-8px;margin-left:-7px;border-radius:4px;background:var(--ac)':''}"></u>${held?`<span class="ab" style="left:${p}%;top:-38px;transform:translateX(-50%);background:var(--ac);color:var(--oa);border-radius:6px;padding:3px 8px;font-size:15px">${v>0?'+':''}${v}</span>`:''}</div>`};
const arow=(l,v,foc,held)=>`<div class="row ${foc?'foc':''}" style="height:50px;gap:12px"><span style="width:106px;${v?'color:var(--ac)':''}">${l}</span>${bip(v,held)}<span style="width:40px;text-align:right;${v?'color:var(--ac)':'color:var(--dm)'}">${v>0?'+':''}${v}</span></div>`;
