NEWS2.forEach(([after,s])=>SCREENS.splice(SCREENS.findIndex(x=>x.id==after)+1,0,s));

// ---------- added: a song's four Show modes; the visualizer alone ----------
// Starfield, still: stars streaming out from the middle of the panel, longer and brighter the further out; TEXT, ACCENT and DIM on BG.
// box: the song's lines (and the art): no star is drawn there, so the text is never crossed
function stars(box=[0,0,0,0],n=110,seed=5){let s=seed,o='';for(let i=0;i<n;i++){s=(s*9301+49297)%233280;const a=s/233280*6.2832;s=(s*9301+49297)%233280;const d=.08+.92*Math.sqrt(s/233280),x=320+Math.cos(a)*d*380,y=240+Math.sin(a)*d*290,w=d>.7?4:d>.4?3:2,c=i%5==0?'ac':d>.45?'tx':'dm';if(x<4||x>632||y<4||y>472||(x>box[0]-16&&x<box[2]&&y>box[1]-8&&y<box[3]))continue;o+=`<i class="ab" style="left:${Math.round(x)}px;top:${Math.round(y)}px;width:${Math.round(w+d*10)}px;height:${w}px;background:var(--${c});transform-origin:0 50%;transform:rotate(${(a*57.2958).toFixed(0)}deg)"></i>`}return `<div class="ab" style="inset:0;overflow:hidden">${o}</div>`}
// with no art in the file: the Art placeholder, in the same box with the same edge (the song's album names it)
const artBox=(sz,noart)=>noart?ph(sz,'Yellow Album',{r:8,st:'box-shadow:0 0 0 2px var(--eds)'}):`<div class="sc-art" style="width:${sz}px;height:${sz}px;flex:none;border-radius:8px;box-shadow:0 0 0 2px var(--eds)"></div>`;
// the art and its text are one group, centred as a group on its real width (the text is as wide as its longest line, capped), in the space given
const artGroup=(sz,top,bottom,info,title='Sunny Peel',noart)=>`<div class="ab" style="left:40px;right:40px;top:${top}px;bottom:${bottom}px;display:flex;align-items:center;justify-content:center;gap:28px">${artBox(sz,noart)}${info?`<div class="in" style="min-width:0;max-width:${560-sz-28}px">${mq(title,'font-weight:600;font-size:28px;line-height:1.2;color:var(--tx)')}<div style="font-size:17px;color:var(--do);margin-top:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">The Plantains</div><div style="font-size:14px;color:var(--dm);margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">Yellow Album · 2026</div></div>`:''}</div>`;
// title, artist and album are always on the top screen (there is no setting): info is kept as a parameter and ignored
// The ground is the theme's BG (app UI: main tokens, so the class pane), all the way down: the visualizer is drawn over it as it was drawn over the art.
// Every style is drawn by the player in the theme's roles (ACCENT, TEXT, DIM) on BG, alone too. Three fill the whole panel (Sparks, Starfield, Sleepy moon): in Art + visualizer they run behind the art, and the art and its lines are centred (style 'stars' draws Starfield)
const musicTop=(mode,info_,style='peaks',title,noart,info=1)=>`<div class="ab pane" style="inset:0;background:var(--bg)"></div>`+
	(mode=='art'?artGroup(info?240:260,0,0,info,title,noart):'')+
	(mode=='artviz'?(style=='stars'?stars([96,118,548,362])+artGroup(info?224:240,0,0,info,title,noart):artGroup(info?224:240,16,176,info,title,noart)+`<div class="ab" style="left:24px;right:24px;bottom:14px">${peaks(52,124)}</div>`):'')+
	(mode=='viz'?(style=='stars'?stars([0,0,330,104]):`<div class="ab" style="left:20px;right:20px;bottom:20px">${peaks(64,340,23)}</div>`)+`<div class="ab in" style="left:22px;top:18px;right:22px">${mq(title||'Sunny Peel','font-weight:600;font-size:26px;color:var(--tx)')}<div style="font-size:17px;color:var(--do);margin-top:5px">The Plantains</div><div style="font-size:14px;color:var(--dm);margin-top:3px">Yellow Album</div></div>`:'')+
	(mode=='none'?`<div class="ab in" style="left:20px;right:20px;top:196px;text-align:center">${mq(title||'Sunny Peel','font-weight:600;font-size:30px;color:var(--tx)')}<div style="font-size:17px;color:var(--dm);margin-top:8px">The Plantains · Yellow Album</div></div>`:'');
const STYLES=['Peaks','Ribbon','Mirror bars','Faders','Horizon','Grid','Starfield','Strings','Helix','Sparks','Bouncy keys','Rocket','Lanterns','Sleepy moon','Dance line'];
const MTABS=['Display','Equalizer','Effects','Speed'];
const SHOWN=['Album art only','Art + visualizer','Visualizer only','None'];
// the app's own marks (src/ui_glyphs.h, rows apart by /): G_PICTURE, G_ARTVIZ, G_VIS_BARS, G_TITLE_ONLY for the four modes, then each style's G_VIS_*
const MODE_G=['###########/#.........#/#......##.#/#......##.#/#....#....#/#...###...#/#..#####..#/#.#######.#/#.........#/###########','###########/#.........#/#......##.#/#......##.#/#.........#/#.....#...#/#.#...#.#.#/#.#.#.#.#.#/#.#.#.#.#.#/###########','.........##/...##....##/...##.##.##/...##.##.##/##.##.##.##/##.##.##.##/##.##.##.##/##.##.##.##','#########/#########/........./.#######./........./..#####..'];
const STYLE_G=['...##....../.........##/##.##....../......##.##/##.##.##.##/##.##.##.##/##.##.##.##/##.##.##.##','.........../...###...../..#...#..../.#.....#..#/#.......##./.........../###########','......#..../..#...#.#../..#.#.#.#../#.#.#.#.#.#/###########/#.#.#.#.#.#/..#.#.#.#../..#...#.#../......#....','.#...#...#./.#..###..#./###..#...#./.#...#...#./.#...#..###/.#...#...#./.#...#...#./.#...#...#.','.........../....###..../...#####.../#.#.###.#.#/###########/.........../#.#######.#/.........../..#.###.#..','....###..../..##...##../##.......##/....###..../..##...##../##.......##/###########','#....#....#/.#.......#./.........../##...#...##/.........../.#.......#./#....#....#','#.........#/#..#####..#/###.....###/#.........#/###########/#.........#/###########/#.........#','#.......#../.#.....#.#./..#...#...#/...#.#...../....#....../...#.#...../..#...#...#/.#.....#.#./#.......#..','....#....../........#../..#......../......#..../.#.......#./....#....../..#...#.#../###########','......##.../......##.../.........../#.##.....##/#.##.#.#.##/#.##.#.#.##/###########/###########','.........../.##......../..####...../##########./#.#########/##########./..####...../.##........','###########/.#...#...#./###.###.###/###.###.###/###.###.###/.#...#...#./.#...#...#.','..###...###/.##......#./##......###/##........./##........./###......##/.########../..#####....','.#.....#.../###...###../#.#.#.#.#.#/..#.....#../..#.....#../.#.#...#.#./.#.#...#.#./###########'];
// a glyph of ui_glyphs.h at 2 units a cell, as the app draws it
const glyph=(g,cell=2)=>{const r=g.split('/'),w=r[0].length;let d='';r.forEach((row,y)=>[...row].forEach((c,x)=>{if(c=='#')d+=`M${x} ${y}h1v1h-1z`}));return `<svg class="i" width="${w*cell}" height="${r.length*cell}" viewBox="0 0 ${w} ${r.length}" fill="currentColor" shape-rendering="crispEdges"><path d="${d}"/></svg>`};
// a choice tile: the one in use is filled (ACCENT, ON_ACCENT ink), the cursor is the ACCENT edge; 56 tall, a thumb's target
const pickTile=(g,l,on,foc,st='')=>`<div class="btn flat ${foc?'foc':''}" style="height:56px;border-radius:10px;gap:4px;white-space:nowrap;${on?'background:var(--ac);color:var(--oa);border-color:var(--ae);':''}${st}">${glyph(g)}<span>${l}</span></div>`;
// View › Display: the four modes in a row, the fifteen styles in a 5 x 3 grid under them. cur: the cursor ('m0'..'m3', 's0'..'s14')
const displaySheet=(show,style,cur='')=>{const hid=show==0||show==3;return sheet(380,`<div class="sh">${ico('viz',20,'color:var(--ac)')}<h2 style="flex:1">Display</h2></div>
	<div class="gl" style="margin:0 0 6px">Top screen shows</div>
	<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">${SHOWN.map((t,i)=>pickTile(MODE_G[i],t,i==show,cur=='m'+i,'flex-direction:row;gap:8px;font-size:13.5px;padding:0 6px'))}</div>
	<div class="fx" style="gap:8px;margin:10px 0 6px"><span class="gl">Visualizer</span><span class="in" style="font-size:12px;color:var(--do)">${STYLES[style]}${hid?' · not shown now: the top screen shows '+SHOWN[show]:''}</span></div>
	<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px">${STYLES.map((t,i)=>pickTile(STYLE_G[i],t,i==style,cur=='s'+i,'flex-direction:column;font-size:12px')).join('')}</div>`.replace(/<\/div>,<div class="btn flat/g,'</div><div class="btn flat'),[['D-pad','Move'],['A','Set'],['SELECT','Next mode'],['B','Close']])};
const mini=(t,cap)=>`<figure><div class="panel"><div class="s${topCls(t)}">${t}</div></div><figcaption><b>${cap[0]}</b> ${cap[1]}</figcaption></figure>`;
{const mv=SCREENS.find(s=>s.id=='music-view');
 mv.why='Display, Equalizer and Effects were three places (a popup, and a page with two tabs). One sheet, four tabs, the same key. Display is one page: what the top screen shows, and which visualizer.';
 mv.bottom=()=>musicB()+displaySheet(1,0,'m1');
 mv.keys=[['D-pad','Move over both groups: the four modes, then the fifteen styles under them',null],['A','Set the mode or the style under the cursor: the top screen changes at once',null],['SELECT','The next mode: Album art only → Art + visualizer → Visualizer only → None','music-viz'],['B','Close','music']];
 mv.notes=[['chg','One Display page for both choices, as in today’s popup: the four modes in a row of icon tiles, the fifteen visualizer styles in a 5 × 3 grid of icon tiles under them. An earlier drawing split them over two tabs (Display, Visualizer); the song’s sheets are now Display, Equalizer, Effects, Speed.'],['same','The icons are the app’s own (ui_glyphs.h): G_PICTURE, G_ARTVIZ, G_VIS_BARS and G_TITLE_ONLY for the modes, each style’s G_VIS_ mark for the styles. None is new.'],['chg','Tiles are the kit’s: 56 tall, a mode 147 wide (icon beside its name), a style 117 wide (icon over its name). The one in use is filled in the accent with the ink that goes on it; the cursor is the accent edge, so the two never look alike. Nothing scrolls: the sheet is 390 tall.'],['chg','The mode and the style are two choices and are never written as one. The Display chip on the player says the mode only. The style is named on the line over the grid, and in Settings.'],['new','With Album art only or None the line over the grid reads “Peaks · not shown now: the top screen shows Album art only”. The styles stay at full strength and can be set: the choice is kept for when a mode shows it. Nothing is dimmed, because nothing is unavailable.'],['chg','The modes are today’s four Show modes; “only” is added to two names so each says all of what it shows. None keeps today’s name; it shows the title alone.'],['chg','The art’s layout changes from today’s app. Today the art is scaled to the full 480 height and the visualizer is laid over its bottom. Here the art is smaller and never covered: in Art + visualizer the bars run in a band along the bottom of the screen, under the art.'],['chg','Title, artist and album are always on the top screen: the Song info on top setting is gone, from here and from Settings. With art, the art sits left and the three lines to its right, the pair centred as a group on its real width (equal margins of 40 units), the text centred on the art’s middle; nothing is ever written over the art. A long title is cut with “…”. Over a visualizer alone they are top left. None is the title alone, centred.'],['new','The ground follows the theme. In Album art only, Art + visualizer and None the top screen’s ground is the theme’s BG, and the title, artist and album are TEXT, DIM_ON and DIM on it: light on a light-bodied theme. The art has a 2-unit edge (the flat piece’s). The ground is the theme’s colour all the way down: in Art + visualizer the style is drawn over it along the foot, the way today’s app draws it over the art, with no strip under it. Every style is drawn by the player in the theme’s colours (ACCENT and TEXT for its marks, DIM for what recedes); none keeps colours of its own. Visualizer only: the style on BG in the same colours, the three lines top left in TEXT, DIM_ON and DIM. Sparks, Starfield and Sleepy moon fill the whole panel; in Art + visualizer they are drawn behind the art, and the art and its lines are centred in the panel as in Album art only. Rocket’s stars fill the panel while the rocket stays in the band. Try the Theme switch.'],['chg','A song with no art (none in the file, no cover.jpg): the Art placeholder (a record in its sleeve, drawn in the theme’s BUTTON, BG, SURFACE and ACCENT) stands in the art’s spot in both art modes, same layout, and by the artist on the bottom screen. Today the app falls back instead. Here the mode you chose is the mode you see.'],['same','In the Display sheet SELECT steps to the next mode, as in today’s popup; B closes. (In the other sheets SELECT closes.)'],['same','The visualizer’s frame rate stays in Settings › Music & sound, unmarked: see State indicators.']];
 mv.extra=()=>`<div class="eyebrow" style="margin-top:16px">The top screen in each mode</div><div class="minis">${mini(musicTop('art'),['Album art only','art left, title, artist and album right'])}${mini(musicTop('artviz'),['Art + visualizer','the same, above the band of bars'])}${mini(musicTop('viz'),['Visualizer only','the whole screen, the three lines top left'])}${mini(musicTop('none'),['None','the title alone'])}${mini(musicTop('artviz',1,'peaks','The Long Way Round the Banana Grove (Live)'),['A long title','a Title marquee: it moves in its box, never under the art'])}${mini(musicTop('art',1,'peaks',undefined,1),['No art in the file','the Art placeholder takes the art’s spot, in the theme’s colours; the layout does not change'])}${mini(musicTop('artviz',1,'peaks',undefined,1),['No art, Art + visualizer','the same at 224'])}${mini(musicB('Art + visualizer','Sunny Peel',1),['No art, the player','the 30-unit placeholder by the artist'])}${mini(musicTop('artviz',1,'stars'),['Art + visualizer, Starfield','a style that fills the panel runs behind the art; the art and its lines are centred'])}${mini(musicTop('viz',1,'stars'),['Visualizer only','Starfield: the whole panel, in the theme’s colours'])}</div>`;}
