const mGrid=(dim)=>{const w=(h,d)=>d&&dim?`<div style="opacity:.45">${h}</div>`:h;return `<div class="fx" style="gap:14px;margin-top:12px;align-items:flex-start">${mcell('bk2','Little Nemo in Slumberland','Winsor McCay','5','foc')}${mcell('bk3','Krazy Kat','George Herriman','12')}${w(mcell('bk6','Moonlit Courier','','2'),1)}${mcell('bk4','Dream of the Rarebit Fiend','Winsor McCay','')}${w(mcell('bk8','Harbor Cats','','1'),1)}</div><div class="fx" style="gap:14px;margin-top:14px;align-items:flex-start">${mcell('bk5','The Yellow Kid','R. F. Outcault','')}${w(mcell('bk7','Tin Robot Diaries','','7'),1)}${mcell('bk1','Buster Brown','R. F. Outcault','')}${w(mcell('bk6','Paper Lantern Alley','','3'),1)}</div>`};
