const netT=(kept)=>`<div class="ab pane" style="inset:0;background:radial-gradient(90% 80% at 20% 40%,color-mix(in srgb,#2a1a33 var(--pt),var(--bg)),var(--bg) 70%)"></div>${tBrand()}<div class="ab" style="left:36px;top:66px">${cover(kept?'bk2':'bk5',kept?'The Time Machine':'Handheld Service Manual',kept?'H. G. Wells':'','',196,278,'padding:18px 16px;border-radius:8px;box-shadow:0 12px 30px rgba(0,0,0,.6),inset 6px 0 0 rgba(0,0,0,.22)')}</div><div class="ab" style="left:262px;right:28px;top:74px"><div class="tk">${kept?'Book · kept on the card':'PDF · on the server'}</div><div style="font-size:27px;margin:8px 0 6px;line-height:1.1">${kept?'The Time Machine':'Handheld Service Manual'}</div><div class="in" style="font-size:15px;color:var(--do)">Media on NAS / Library</div><dl class="tmeta" style="margin:18px 0;font-size:13.5px">${kept?'<dt>Opens</dt><dd class="ac">At once: a copy is on the card</dd><dt>Read</dt><dd>58% · Chapter 7 of 12</dd><dt>Copies kept</dt><dd>214 MB of 2 GB</dd>':'<dt>Opens</dt><dd>After a copy to the card: 8.4 MB</dd><dt>Why</dt><dd>So a dropped connection can’t take the page away</dd><dt>Room</dt><dd>21 GB free on This card</dd>'}</dl>${tHint([['A',kept?'Read':'Copy and open'],['X','More']])}</div>`;
const copySheet=(state)=>sheet(state?300:270,state=='lost'?`<div class="sh">${ico('network',20,'color:var(--dg)')}<h2 style="flex:1;color:var(--dg)">Lost the connection</h2><span class="in dm" style="font-size:12.5px">at 37%</span></div><div class="in" style="font-size:14px;line-height:1.5;padding:0 2px">Handheld Service Manual.pdf was not copied. Nothing half-copied is left on the card.</div><div class="in dm" style="font-size:13px;line-height:1.5;padding:6px 2px 0">Media on NAS didn’t answer for 20 seconds. Check the Wi-Fi, then try again: it starts from the beginning.</div><div class="fx" style="gap:10px;margin-top:16px"><div class="btn acc" data-go="net-copy" style="flex:1;height:56px;font-size:17px">Try again${cap('A')}</div><div class="btn" data-go="net-folder" style="flex:1;height:56px;font-size:17px">Close${cap('B')}</div></div>`:
	state=='full'?`<div class="sh">${ico('card',20,'color:var(--dg)')}<h2 style="flex:1;color:var(--dg)">Not enough room on the card</h2></div><div class="in" style="font-size:14px;line-height:1.5;padding:0 2px">Moonlit Courier v02.cbz needs 64 MB. This card has 12 MB free.</div><div class="in dm" style="font-size:13px;line-height:1.5;padding:6px 2px 0">Checked before copying: nothing was written. Copies of network books you opened take 1.9 GB; the oldest can go.</div><div class="fx" style="gap:10px;margin-top:16px"><div class="btn acc" style="flex:1;height:56px;font-size:17px">Clear old copies · 1.9 GB${cap('A')}</div><div class="btn" style="flex:1;height:56px;font-size:17px">Close${cap('B')}</div></div>`:
	`<div class="sh">${ico('download',20,'color:var(--ac)')}<h2 style="flex:1">Copying to the card</h2><span class="in dm" style="font-size:12.5px">then it opens</span></div><div style="font-size:17px;padding:0 2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">Handheld Service Manual.pdf</div><div class="bar" style="height:12px;border-radius:6px;margin:14px 2px 8px"><i style="width:37%"></i></div><div class="fx in" style="justify-content:space-between;font-size:13px;color:var(--do);padding:0 2px"><span>3.1 of 8.4 MB · 37%</span><span>about 6 s left · from Media on NAS</span></div><div class="fx" style="gap:10px;margin-top:16px"><div class="btn" data-go="net-folder" style="flex:1;height:56px;font-size:17px">Cancel${cap('B')}</div></div>`,state?[['A',state=='full'?'Clear':'Try again'],['B','Close']]:[['B','Cancel: nothing is left behind']]);
const spin=(sz=54)=>`<div style="width:${sz}px;height:${sz}px;border-radius:50%;border:5px solid var(--bt);border-top-color:var(--ac);border-right-color:var(--ac)"></div>`;
const streamT=(t,sub,hint,err)=>`<div class="ab sc-steel" style="inset:0;filter:brightness(.35)"></div><div class="ab col" style="left:40px;right:40px;top:150px;align-items:center;text-align:center">${err?ico('network',48,'color:var(--dg)'):spin()}<div style="font-size:26px;margin-top:16px;color:${err?'var(--dg)':'var(--ac)'}">${t}</div><div class="in" style="font-size:15px;color:var(--tx);margin-top:8px">${sub}</div>${hint?`<div class="in fx" style="gap:8px;font-size:14px;color:var(--do);margin-top:16px">${hint}</div>`:''}</div>`;
