const tInfo=(tk,title,text,rows=[],hint=[],red)=>`<div class="ab pane" style="inset:0;background:var(--bg)"></div>${tBrand()}<div class="ab" style="left:44px;right:44px;top:74px"><div class="tk" style="${red?'color:var(--dg)':''}">${tk}</div><div style="font-size:28px;margin:8px 0 8px;line-height:1.15">${title}</div><div class="in" style="font-size:14.5px;color:var(--do);line-height:1.5">${text}</div>${rows.length?`<dl class="tmeta" style="margin:18px 0 0;font-size:13.5px">${rows.map(r=>`<dt>${r[0]}</dt><dd>${r[1]}</dd>`).join('')}</dl>`:''}${hint.length?`<div style="margin-top:18px">${tHint(hint)}</div>`:''}</div>`;
const alertS=(t,x,ok='OK',red)=>sheet(226,`<div class="sh">${ico('info',20,`color:var(--${red?'dg':'ac'})`)}<h2 style="flex:1;${red?'color:var(--dg)':''}">${t}</h2></div><div class="in" style="font-size:14px;line-height:1.5;padding:0 2px;min-height:44px">${x}</div><div class="btn acc" style="height:56px;margin-top:14px;font-size:17px">${ok}${cap('A')}</div>`,[['A/B','Close']]);
const askS=(h,ic,t,x,safe,act,red,foot='')=>sheet(h,`<div class="sh">${ico(ic,20,`color:var(--${red?'dg':'ac'})`)}<h2 style="flex:1;${red?'color:var(--dg)':''}">${t}</h2></div><div class="in" style="font-size:14px;line-height:1.5;padding:0 2px">${x}</div>${foot}<div class="fx" style="gap:10px;margin-top:16px"><div class="btn acc" style="flex:1;height:56px;font-size:17px">${safe}${cap('B')}</div><div class="btn" style="flex:1;height:56px;font-size:17px;${red?'color:var(--dg)':''}">${act}</div></div>`,[['◀/▶','Choose'],['A','OK'],['B',safe]]);
