SCREENS.splice(SCREENS.findIndex(x=>x.id=='power-awake')+1,0,
{id:'web-signin',group:'System',name:'A browser signs in',isNew:0,why:'Someone opening your files from another device is worth a line, once, on the top screen: who, from where, when. It is the note component, with one rule about when it may interrupt a film.',
 top:()=>tInfo('Files › Videos › Movies','Sintel','14:48 · 8 chapters · 1.1 GB · not played yet',[['Picture','H.264 · 1920 × 818'],['Audio','English 5.1, Italiano'],['Subtitles','English, Español + 6']])+toast('Chrome on Mac signed in','Web dashboard · 192.168.1.14 · 21:47','globe'),
 bottom:()=>shell('files',{title:'Movies',crumb:'Files  ›  Videos  ›  Movies',back:'home',more:'',st:{web:'1'},body:folderRows(),hint:[['A','Play'],['B','Up'],['X','More'],['Y','Select'],['L/R','Section']]}),
 keys:[['(nothing to press)','The note goes by itself after 6 seconds',null],['Tap the globe','The Web dashboard page: who is signed in, New PIN, Sign everyone out','web-page'],['B','Up a folder, as usual','home'],['A','Play / open, as usual','video'],['X','More','actions'],['Y','Select','select'],['L','Previous section','home'],['R','Next section','videos']],
 notes:[['same','When a browser signs in, a note pops up on the top screen; the globe is dim with nobody connected and yellow with someone; a tap on it opens the dashboard page.'],['chg','The note says who (browser and device), the address it came from, and the time, and stays 6 seconds. The globe becomes a yellow badge with how many browsers are signed in.'],['new','Over a playing video: a sign-in with the PIN (a browser the handheld has not seen) is always shown, film or not: it is the one note that may appear by itself, because it is about access to your files. A browser that was already signed in and merely comes back changes the globe only.'],['new','A second browser: the same note, with “2 browsers signed in” as its second line. Signing out, or being signed out by New PIN: a 3-second note, never over a video.'],['new','Wrong PINs: recommended to show. After five wrong tries from one device the handheld says so in red (“5 wrong PINs from 192.168.1.37 · it must wait 60 s”), film or not, because someone is guessing. After thirty in all, “The PIN was changed” (as today), with the new PIN on the dashboard page.'],['new','Each of these is also a line under “Browsers signed in” on the dashboard page, so a note you missed can be read later.']],
 extra:()=>`<div class="minis">${mini(videoT(false)+toastV('Safari on iPhone signed in','2 browsers signed in · 192.168.1.22 · 21:52','globe'),['A second browser','over a video too: it used the PIN'])}${mini(tInfo('Files › Videos › Movies','Sintel','14:48 · 1.1 GB')+toast('Chrome on Mac signed out','1 browser signed in','globe'),['Signed out','3 s, never over a video'])}${mini(tInfo('Settings › Web dashboard','New PIN','Every browser must sign in again.')+toast('Every browser was signed out','New PIN · it is on the dashboard page','globe'),['New PIN','signs everyone out'])}${mini(videoT(false)+toastV('5 wrong PINs from 192.168.1.37','It must wait 60 s before trying again','lock',1),['Wrong PINs','red, shown over a video'])}${mini(tInfo('Files › Videos › Movies','Sintel','14:48 · 1.1 GB')+toast('The PIN was changed','30 wrong tries in all · every browser signed out','lock',1),['After 30 wrong tries','as today, in the note’s shape'])}${mini(globeStrip(),['The globe','its four states'])}</div>`});

// ---------- added: long track names; long chapter lists ----------
const NL=`font-family:'Noto Sans JP','Noto Sans Arabic','Noto Sans Thai','Hiragino Sans','Yu Gothic','Geeza Pro',Inter,sans-serif;font-weight:600`;
const trow=(l1,l2,o={})=>`<div class="row ${o.foc?'foc':''}" style="height:60px"><i style="width:14px;height:14px;border-radius:7px;flex:none;border:2px solid ${o.on?'var(--ac)':'var(--dm)'};${o.on?'box-shadow:inset 0 0 0 3px var(--bt),inset 0 0 0 8px var(--ac)':''}"></i><span class="col" style="flex:1;min-width:0;gap:5px"><span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis;${o.foc?'color:var(--ac)':''}">${l1}</span><span class="in" style="font-size:12px;color:var(--${o.foc?'do':'dm'});white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${l2}</span></span>${o.pill||''}</div>`;
const subRows=()=>`<div class="row"><i style="width:14px;height:14px;border-radius:7px;border:2px solid var(--dm)"></i><span class="nm">Off</span></div>`+
	trow('Português (Brasil)','SDH · Forced · SRT · in the file',{on:1,foc:1})+
	trow('English','Full · ASS, styled · in the file')+
	trow(`<span style="${NL}">日本語</span> (Japanese)`,'Signs &amp; Songs · ASS, styled · in the file')+
	trow(`<span dir="rtl" style="${NL}">العربية</span> (Arabic)`,'SRT · in the file')+
	trow('English','Forced · Big.Buck.Bunny.2008.1080p…en.forced.srt',{pill:pill('File','n')});
const audRows=()=>trow('English','AAC 5.1 · the film’s own',{on:1})+
	trow('English','Commentary with director and cast · AC-3 5.1',{foc:1,pill:pill('Commentary','n')})+
	trow('Português (Brasil)','Dublado · AAC stereo')+
	trow(`<span style="${NL}">日本語</span> (Japanese)`,'FLAC 2.0')+
	trow('Unknown language','Track 5 · no name in the file · DTS 5.1');
const longVideoB=(x={})=>videoB('',x).replace('>English</span></span></div>','>Português</span></span></div>').replace('>English 5.1<','>English · Co…<');
const chRow=(n,t,time,o={})=>`<div class="row ${o.foc?'foc':''}">${o.foc?ico('play',13,'color:var(--ac)'):`<span class="dm" style="width:22px;text-align:right;font-size:15px">${n}</span>`}<span class="nm">${t}</span>${o.foc?pill('Now'):''}<span class="nt">${time}</span></div>`;
const chSheet=(named)=>sheet(420,`<div class="sh">${tabs(['Up next','Chapters 42'],1,{0:'video-list'})}<span style="flex:1"></span><span class="in dm" style="font-size:12.5px">17 of 42 · ◀ ▶ a page</span></div>
	${named?chRow(15,'The Road North','38:12')+chRow(16,'An Inn at the Edge of the Marshes, Where Nobody Asks Questions','41:55')+chRow(17,'The Ferryman’s Bargain','45:03',{foc:1})+chRow(18,'What the Lantern Showed, and What It Did Not','48:40')+chRow(19,'Low Water','52:16')+chRow(20,'The Second Letter','55:02')+chRow(21,'Night Crossing','57:48'):
	chRow(15,'Chapter 15','38:12')+chRow(16,'Chapter 16','41:55')+chRow(17,'Chapter 17','45:03',{foc:1})+chRow(18,'Chapter 18','48:40')+chRow(19,'Chapter 19','52:16')+chRow(20,'Chapter 20','55:02')+chRow(21,'Chapter 21','57:48')}
	<div class="ab" style="right:5px;top:76px;bottom:38px;width:4px;border-radius:2px;background:var(--tr)"><i class="ab" style="left:0;right:0;top:36%;height:17%;border-radius:2px;background:var(--pr)"></i></div>`,[['▲/▼','Move'],['◀/▶','Page'],['A','Play from here'],['L2/R2','Chapter'],['Y/B','Close']]);
const chLine=(t)=>`<div class="btn flat" style="height:40px;padding:0 10px;gap:8px;justify-content:flex-start;flex:1;min-width:0">${ico('list',16)}<span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;text-align:left">${t}</span>${caps('L2/R2')}${ico('chevR',14,'color:var(--dm)')}</div>`;
const chVideoB=(t)=>videoB().replace(/<div class="btn flat" style="height:40px;padding:0 10px;gap:8px;justify-content:flex-start;flex:1">.*?<\/div>/s,chLine(t)).replace('5 / 7','1 / 3');
