const TAP_MISS=[];
const tapOn=(id,h,[label,go])=>{
	const from=h.lastIndexOf('class="veil"')+1,at=h.indexOf('>'+label,from);
	const m=at<0?null:[...h.slice(from,at+1).matchAll(/<(?:div|span) class="(?:btn|row|tab|chip)\b[^>]*>/g)].pop();
	if(!m){TAP_MISS.push(id+': '+label);return h}
	const i=from+m.index,tag=/data-go="/.test(m[0])?m[0].replace(/data-go="[^"]*"/,`data-go="${go}"`):m[0].replace(/^<(div|span) /,`<$1 data-go="${go}" `);
	return h.slice(0,i)+tag+h.slice(i+m[0].length);
};
SCREENS.forEach(s=>{s.also=ALSO[s.id]||[];const t=TAPS[s.id];if(t&&t.length){const b=s.bottom;s.bottom=(...a)=>t.reduce((h,x)=>tapOn(s.id,h,x),b(...a))}});
